CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), apple_subject text UNIQUE NOT NULL, display_name text, email text, app_account_token uuid UNIQUE NOT NULL DEFAULT gen_random_uuid(), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE apple_auth_credentials (user_id uuid PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, refresh_token_encrypted text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE devices (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, installation_id uuid NOT NULL, platform text NOT NULL, device_label text NOT NULL, app_version text, created_at timestamptz NOT NULL DEFAULT now(), last_seen_at timestamptz NOT NULL DEFAULT now(), revoked_at timestamptz); CREATE UNIQUE INDEX devices_user_installation ON devices(user_id,installation_id);
CREATE TABLE sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, device_id uuid NOT NULL REFERENCES devices(id) ON DELETE CASCADE, refresh_token_hash text UNIQUE NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz NOT NULL, last_seen_at timestamptz NOT NULL DEFAULT now(), revoked_at timestamptz);
CREATE TABLE auth_challenges (id uuid PRIMARY KEY, nonce_hash text NOT NULL, state text NOT NULL, installation_id uuid NOT NULL, expires_at timestamptz NOT NULL, used_at timestamptz);
